  async setRvalue(mdl: presentSetupData): Promise<any> {
    let res: any = [];
    try {
      this.presentSession = Object.assign(this.presentSession, mdl);
      res = await firstValueFrom(
        this.http.post<TypeRes[]>(
          `${environment.presentationservice}/present/setup/setsetup`,
          mdl
        )
      );
    } catch (error) {
      console.error(error);
      res = {};
    }
    return res;
  }

