  async getTeam(cType: string, nCaseid: string): Promise<presentTeams[]> {
    let res: any = [];
    try {
      const params = new HttpParams()
        .set('cType', cType)
        .set('nCaseid', nCaseid);
      res = await firstValueFrom(
        this.http.get<any[]>(
          `${environment.presentationservice}/present/setup/teams/users`,
          { params: params }
        )
      );
    } catch (err) {
      console.error(err);
      res = [];
    }
    return await this.userPermissionArrenge(res);
  }

  async userPermissionArrenge(res): Promise<presentTeams[]> {
    if (!res) {
      return [];
    }
    let teamList = res[0];
    for (let x of res[0]) {
      x.users = [];
      x.users = res[1].filter((a) => a.nTeamid == x.nTeamid);
    }
    return teamList;
  }

