  async downloadFiles(args: downloadReport): Promise<any> {
    let nUserid = await this.sStore.getUserId();
    var link = document.createElement('a');
    let params = btoa(JSON.stringify(args))
    link.href = `${environment.downloadservice}/download/downloadPresentReport?nMasterid=${nUserid}&params=${params}`;
    link.setAttribute('download', ('folder'));

    link.addEventListener('load', function () {
      console.log('Download started');
    });

    // Add an event listener to handle errors and hide the loading indicator
    link.addEventListener('error', function () {
      // t.isDownLoading = false;
      console.error('Error downloading file');
    });
    link.addEventListener('click', function () {
      // t.isDownLoading = false;
      console.log('Download link clicked');
    });

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }


